import {challenge as C} from './shared.js';
export default [
C(8,2,'从轨迹生成动作条件转移',{
 goal:'对齐状态、动作与下一状态，阻止跨 episode 构造假转移。',signature:'transitions(episodes)',contract:'episodes 每项为 {"states":长度T+1列表,"actions":长度T列表}，状态和动作均为标量。返回按原顺序的 (state,action,next_state) 三元组列表。',context:'世界模型常预测执行动作后的状态。动作错开一帧时，训练仍可能从连续状态中取得低误差，却没有学到正确控制关系。先明确 a_t 把 s_t 推到 s_(t+1)，再切片。',steps:['逐条 episode 处理，状态终点不作为新动作的起点。','对每个动作下标 t 取 states[t] 与 states[t+1]。','输出顺序保持稳定，独立 episode 之间不添加转移。'],worked:['states=[0,1,3]，actions=[1,2]。','对应 (0,1,1)、(1,2,3)。','下一条轨迹即使从 100 开始，也不能生成 (3,某动作,100)。'],mistake:'先把所有 states 拼接再切相邻对，会制造不存在的环境跳变。',transfer:'真实数据还需核对时间戳、控制频率、延迟和终止状态；三元组形状正确不意味着动作语义正确。',cases:[['transitions([{"states":[0,1,3],"actions":[1,2]}])','[(0,1,1),(1,2,3)]','动作与结果对齐'],['transitions([{"states":[0,1],"actions":[1]},{"states":[10,12],"actions":[2]}])','[(0,1,1),(10,2,12)]','不跨轨迹'],['transitions([{"states":[5],"actions":[]}])','[]','没有动作']],solution:'def transitions(episodes):\n    return [(ep["states"][t],a,ep["states"][t+1]) for ep in episodes for t,a in enumerate(ep["actions"])]\n',quiz:['a_t 的目标应对齐哪个状态？',['s_t','s_(t+1)','任意未来帧'],1,'前提是数据定义 a_t 在 s_t 后执行；真实项目必须查证这个约定。']
}),
C(8,4,'计算目标区域的表示预测误差',{
 goal:'只对被选作目标的表示位置计算平均平方误差。',signature:'representation_loss(predicted, target, mask)',contract:'predicted、target 为 N×D 矩阵，mask 长 N；True 表示目标位置。按所有选中位置的全部坐标平均平方误差；没有目标位置时抛 ValueError。',context:'JEPA 类方法在表示空间预测目标，不要求解码成像素。目标区域的选择影响模型学什么。这个数值题只检查损失位置与归一化，普通 Python 列表没有梯度图，不能用它证明目标分支停止了梯度。',steps:['找出 mask=True 的位置，忽略其他位置的误差。','对选中位置逐坐标累积平方误差。','分母为目标位置数乘 D，不是整张图的位置数。'],worked:['两个位置、每个二维，只选择第二个。','第二个预测 [1,3]、目标 [1,1]，平方误差 [0,4]。','平均为 2，第一位置再大的错误也不计入此目标。'],mistake:'低表示误差可能来自塌缩；所有表示变成常数也能制造低损失。',transfer:'真实 JEPA 还需目标编码器、停止梯度和防塌缩设计；本题帮助审查 loss 的位置和分母。',cases:[['representation_loss([[99,99],[1,3]],[[0,0],[1,1]],[False,True])','2','只对目标区域计分'],['representation_loss([[1,2]],[[1,2]],[True])','0','完全相同'],['representation_loss([[1],[3]],[[0],[0]],[True,True])','5','跨位置平均']],extraTests:[{name:'无目标拒绝伪造损失',code:'try:\n    representation_loss([[1]],[[1]],[False])\n    assert False\nexcept ValueError: pass'}],solution:'def representation_loss(predicted,target,mask):\n    errors=[(x-y)**2 for a,b,ok in zip(predicted,target,mask) if ok for x,y in zip(a,b)]\n    if not errors: raise ValueError("no targets")\n    return sum(errors)/len(errors)\n',quiz:['表示误差接近零，能否单独证明学到了有用语义？',['能','不能，要排查塌缩和下游表现','只有维度大才可以'],1,'目标与预测一起退化为常数也可能使误差很小。']
}),
C(8,6,'比较单步与自由运行误差',{
 goal:'用同一动态模型计算 teacher-forcing 与 free-running 两条误差曲线。',signature:'compare_rollouts(states, actions, gain)',contract:'states 长 T+1，actions 长 T≥1。模型 next=s+gain*a。返回 {"teacher":每步平方误差列表,"free":每步平方误差列表}；free 只能从 states[0] 开始使用自己的预测。',context:'单步评测每次都得到真实起点，自由运行必须承受自己的历史错误。把真实状态塞回 free-running 循环会得到好看的曲线，却回答不了连续预测能否稳定的问题。',steps:['teacher 每次用 states[t] 预测下一项。','free 维护一个预测状态变量，每一步更新后继续使用。','states[t+1] 仅用于计算两条误差，不用于重置 free 的预测状态。'],worked:['真实状态 [0,1,2]，动作 [1,1]，gain=0.5。','teacher 每步误差平方都是 0.25。','free 预测 [0.5,1]，误差平方是 [0.25,1]。'],mistake:'在两个循环中都读取 states[t] 会让曲线完全一样，掩盖误差积累。',transfer:'真实报告应保留按 horizon 的曲线，并控制初始状态、动作与目标对齐。',cases:[['compare_rollouts([0,1,2],[1,1],0.5)','{"teacher":[0.25,0.25],"free":[0.25,1]}','误差积累'],['compare_rollouts([0,1,3],[1,2],1)','{"teacher":[0,0],"free":[0,0]}','准确模型'],['compare_rollouts([2,1,0],[-1,-1],0)','{"teacher":[1,1],"free":[1,4]}','忽略动作退化']],solution:'def compare_rollouts(states,actions,gain):\n    teacher=[]; free=[]; state=states[0]\n    for t,a in enumerate(actions):\n        teacher.append((states[t]+gain*a-states[t+1])**2)\n        state=state+gain*a\n        free.append((state-states[t+1])**2)\n    return {"teacher":teacher,"free":free}\n',quiz:['连续预测第二步应输入什么？',['真实第二帧','上一时刻的预测状态','验证目标'],1,'目标只参与评测；输入真实历史属于另一种评测条件。']
}),
C(8,7,'周项目：学习动作增益并闭环预测',{
 goal:'用训练转移学习一个动态参数，再在独立动作序列上 rollout。',signature:'train_world(train, initial, actions, steps, lr)',contract:'train 为非空 (s,a,next_s) 列表。模型 next=s+gain*a，gain 从 0 开始，用平均平方损失梯度更新 steps 次。返回 {"gain":数值,"rollout":包含初始状态的预测列表}。',context:'模型结构已经规定状态如何依赖动作，训练需要从样本估计 gain。它是一个真正经过参数更新的最小世界模型，但表达能力只有一维线性动态。它能支持你验证学习、泛化与动作条件三个问题，不能代表视觉世界模型的全部难度。',steps:['每次计算 error=s+gain*a-next_s，梯度为平均 2*error*a。','更新 gain，始终只使用 train。','训练结束后从 initial 出发连续应用动作，保存全部状态。'],worked:['训练 [(0,1,2),(1,1,3)]，真实增益为 2。','gain=0 时梯度 -4；lr=0.5，一步更新到 2。','initial=5，actions=[1,-1]，rollout=[5,7,5]。'],mistake:'rollout 时再次训练 gain 会混淆学习与预测阶段。',transfer:'下一步可在 tiny_world_model.py 中用神经网络扩展结构，并比较单步、长程和动作打乱指标。',cases:[['train_world([(0,1,2),(1,1,3)],5,[1,-1],1,0.5)','{"gain":2,"rollout":[5,7,5]}','训练后预测'],['train_world([(0,1,2)],5,[1,2],0,0.1)','{"gain":0,"rollout":[5,5,5]}','零步基线'],['train_world([(3,0,3)],2,[1],10,0.1)','{"gain":0,"rollout":[2,2]}','无动作信息无法学习增益']],extraTests:[{name:'学习非单位增益',code:'r=train_world([(0,1,0.7),(0,-1,-0.7)],0,[1,1],100,0.1)\nassert abs(r["gain"]-0.7)<1e-8 and abs(r["rollout"][-1]-1.4)<1e-8'}],solution:'def train_world(train,initial,actions,steps,lr):\n    gain=0.0\n    for _ in range(steps):\n        grad=sum(2*(s+gain*a-y)*a for s,a,y in train)/len(train)\n        gain-=lr*grad\n    state=initial; path=[state]\n    for a in actions:\n        state+=gain*a; path.append(state)\n    return {"gain":gain,"rollout":path}\n',quiz:['训练里所有动作都是 0，能靠这些样本学到动作增益吗？',['一定能','不能从这些动作得到增益梯度','只要多训练就能'],1,'对 gain 的梯度含 a，全部为零时这条学习信号消失。']
})];
